CAPITAL_HTML = "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>TimePressure Capital</title><style>body{background:#090b10;color:#f4f7fb;font:14px system-ui;padding:28px}main{max-width:1200px;margin:auto}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:#10131a;border:1px solid #252b36;border-radius:14px;padding:18px}.label{color:#8993a3;font-size:12px}.value{font-size:26px;font-weight:800;margin-top:8px}.safe{color:#50d890}.warn{color:#f2c14e}.bad{color:#ff6577}button{background:#18202c;color:#fff;border:1px solid #303846;border-radius:8px;padding:10px 14px;margin:4px}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #252b36;text-align:left}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.grid{grid-template-columns:1fr}}</style></head><body><main><p class=\"label\">TIMEPRESSURE / CAPITAL</p><h1>Wallet & Financial Control</h1><div id=\"status\"></div><div class=\"grid\" id=\"cards\"></div><div class=\"card\" style=\"margin-top:14px\"><b>Controls</b><div><button onclick=\"mode('paper')\">Paper Mode</button><button onclick=\"mode('live')\">Live Mode</button><button onclick=\"stopAll()\">Emergency Stop</button><button onclick=\"pause()\">Pause All Financial Operations</button></div></div><div class=\"card\" style=\"margin-top:14px\"><b>Transaction History</b><table><thead><tr><th>Time</th><th>Source</th><th>Type</th><th>Amount</th><th>Balance</th><th>Status</th></tr></thead><tbody id=\"ledger\"></tbody></table></div></main><script>async function get(){return (await fetch('/api/capital',{cache:'no-store'})).json()}function esc(s){return String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]))}async function render(){const d=await get(),b=d.wallet.balances;document.getElementById('status').innerHTML='<p class=\"'+(d.risk.emergency_stop?'bad':d.risk.mode==='LIVE'?'warn':'safe')+'\">'+esc(d.risk.emergency_stop?'BLOCKED — EMERGENCY STOP':d.risk.mode+' MODE')+'</p>';const rows=[['Total Capital',d.wallet.total],['Available',b.AVAILABLE],['Reserved',b.RESERVED],['Savings',b.SAVINGS],['Trading',b.TRADING],['Pending',b.PENDING],['Profit',b.PROFIT],['Loss',b.LOSS]];document.getElementById('cards').innerHTML=rows.map(x=>'<div class=\"card\"><div class=\"label\">'+x[0]+'</div><div class=\"value\">$'+Number(x[1]||0).toFixed(2)+'</div></div>').join('');document.getElementById('ledger').innerHTML=d.wallet.ledger.slice(-100).reverse().map(x=>'<tr><td>'+new Date(x.timestamp*1000).toLocaleString()+'</td><td>'+esc(x.source)+'</td><td>'+esc(x.type)+'</td><td>$'+Number(x.amount).toFixed(2)+'</td><td>$'+Number(x.balance_after).toFixed(2)+'</td><td>'+esc(x.status)+'</td></tr>').join('')||'<tr><td colspan=\"6\">No transactions.</td></tr>'}async function post(body){await fetch('/api/capital',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});render()}function mode(v){post({action:'mode',value:v})}function stopAll(){post({action:'switch',name:'emergency_stop',value:true})}function pause(){post({action:'switch',name:'pause_all',value:true})}render();setInterval(render,5000)</script></body></html>"
